1	package nexusfixture
2	
3	import (
4		"net/http"
5		"regexp"
6		"strconv"
7		"strings"
8	)
9	
10	// redacted is what replaces a credential or a secret value in a fixture.
11	const redacted = "<redacted>"
12	
13	// Authorization values a fixture may carry: the scheme and nothing else.
14	const (
15		authBasicRedacted  = "Basic " + redacted
16		authBearerRedacted = "Bearer " + redacted
17	)
18	
19	// ResponseHeaderAllowlist is the closed list of response headers a fixture
20	// keeps: everything else (Date, Set-Cookie, proxy and Nexus internals) is
21	// dropped by Redact and refused by CheckLeaks.
22	var ResponseHeaderAllowlist = []string{
23		"Server", "Docker-Distribution-Api-Version", "WWW-Authenticate", "Location", "Link",
24		"Docker-Content-Digest", "Content-Type", "Content-Length",
25	}
26	
27	// requestHeaderAllowlist is what Redact keeps of a request, besides the
28	// normalized Authorization.
29	var requestHeaderAllowlist = []string{"Accept"}
30	
31	// RawExchange is an exchange as the recorder read it from a Nexus: nothing is
32	// redacted yet, so it must never be written to a file as is.
33	type RawExchange struct {
34		Method, Target, Host string
35		RequestHeader        http.Header
36		Status               int
37		Header               http.Header
38		Body                 []byte
39	}
40	
41	// secretJSON matches a JSON member whose key names a secret: group 1 is the
42	// key and the colon, group 2 the value (a string, or a bare number or literal).
43	// Matching is textual so that a replaced body keeps every other byte as sent.
44	var secretJSON = regexp.MustCompile(
45		`("(?:token|access_token|refresh_token|password|secret|uploaderIp)"\s*:\s*)("(?:[^"\\]|\\.)*"|[^\s,}\]"{\[]+)`)
46	
47	var htmlTitle = regexp.MustCompile(`(?is)<title[^>]*>(.*?)</title>`)
48	
49	// Redact turns a raw exchange into one that is safe to write to a fixture: the
50	// Authorization value becomes a placeholder, request and response headers are
51	// filtered to their allowlists, an HTML body is summarized, an empty one is
52	// marked, and the values of the secret JSON keys are replaced in place. It does
53	// not modify raw.
54	func Redact(raw RawExchange) Exchange {
55		ex := Exchange{
56			Method: raw.Method, Target: raw.Target, Host: raw.Host,
57			RequestHeader: redactRequestHeader(raw.RequestHeader),
58			Status:        raw.Status,
59			Header:        http.Header{},
60		}
61		for _, name := range ResponseHeaderAllowlist {
62			if values := raw.Header.Values(name); len(values) > 0 {
63				ex.Header[http.CanonicalHeaderKey(name)] = append([]string(nil), values...)
64			}
65		}
66		switch {
67		case len(raw.Body) == 0:
68			ex.Stub = stubEmpty
69		case isHTML(raw.Header, raw.Body):
70			ex.Stub = htmlStub(raw.Body)
71		default:
72			ex.Body = []byte(redactSecretJSON(string(raw.Body)))
73		}
74		return ex
75	}
76	
77	func redactRequestHeader(in http.Header) http.Header {
78		out := http.Header{}
79		if auth := in.Get("Authorization"); auth != "" {
80			scheme, _, _ := strings.Cut(strings.TrimSpace(auth), " ")
81			switch strings.ToLower(scheme) {
82			case "basic":
83				out.Set("Authorization", authBasicRedacted)
84			case "bearer":
85				out.Set("Authorization", authBearerRedacted)
86			}
87			// Any other scheme carries a secret we cannot place: the header is dropped.
88		}
89		for _, name := range requestHeaderAllowlist {
90			if values := in.Values(name); len(values) > 0 {
91				out[http.CanonicalHeaderKey(name)] = append([]string(nil), values...)
92			}
93		}
94		return out
95	}
96	
97	func isHTML(h http.Header, body []byte) bool {
98		if strings.Contains(strings.ToLower(h.Get("Content-Type")), "text/html") {
99			return true
100		}
101		head := strings.ToLower(strings.TrimSpace(string(body[:min(len(body), 64)])))
102		return strings.HasPrefix(head, "<!doctype html") || strings.HasPrefix(head, "<html")
103	}
104	
105	// htmlStub summarizes an HTML body as "<HTML body omitted: N bytes, <title>T</title>>"
106	// (the title is left out when there is none). The title is flattened to one
107	// line so that the stub stays one.
108	func htmlStub(body []byte) string {
109		stub := stubHTMLStart + " " + strconv.Itoa(len(body)) + " bytes"
110		if m := htmlTitle.FindSubmatch(body); m != nil {
111			stub += ", <title>" + strings.Join(strings.Fields(string(m[1])), " ") + "</title>"
112		}
113		return stub + ">"
114	}
115	
116	// redactSecretJSON replaces the value of each secret JSON key with "<redacted>".
117	// A null value is kept: it holds no secret.
118	func redactSecretJSON(body string) string {
119		return secretJSON.ReplaceAllStringFunc(body, func(m string) string {
120			sub := secretJSON.FindStringSubmatch(m)
121			if sub[2] == "null" {
122				return m
123			}
124			return sub[1] + `"` + redacted + `"`
125		})
126	}
