1	package nexusfixture
2	
3	import (
4		"bytes"
5		"fmt"
6		"net/http"
7		"net/textproto"
8		"regexp"
9		"sort"
10		"strconv"
11		"strings"
12		"time"
13	)
14	
15	// Identity is the account a fixture was recorded as; it comes from the file
16	// name suffix only.
17	type Identity string
18	
19	// The identities of the NX-03 bench.
20	const (
21		Admin     Identity = "admin"
22		Pull      Identity = "pull"
23		Anonymous Identity = "anon"
24	)
25	
26	// RecordPending marks a request-only fixture that the recorder has yet to fill.
27	const RecordPending = "pending"
28	
29	const (
30		fileSuffix    = ".http"
31		identitySep   = "--"
32		exchangeSep   = "###"
33		httpVersion   = "HTTP/1.1"
34		stubEmpty     = "<empty body>"
35		stubHTMLStart = "<HTML body omitted:"
36	)
37	
38	// Meta is the commented header of a fixture. Free text is kept raw so that
39	// Format loses nothing.
40	type Meta struct {
41		Scenario     string // the "# scenario:" header, free text; Fixture.Scenario is the file name's part
42		NexusVersion string // first token of the nexus header
43		Edition      string // second token of the nexus header
44		NexusNote    string // the text in parentheses after the edition, without them
45		Measured     string // raw value: a date, optionally followed by ", free text"
46		Account      string
47		Redacted     string
48		State        string // "" = nominal
49		Record       string // "" = replay, "replay", "pending" or "skip: <reason>"
50		RecordedBy   string // "" for an imported NX-03 file
51	}
52	
53	// Exchange is one request and its answer. A request-only exchange (a pending
54	// fixture) has Status 0 and no response part.
55	type Exchange struct {
56		Method, Target, Host string // Target = path + raw query as recorded
57		RequestHeader        http.Header
58		Status               int
59		Reason               string      // reason phrase as recorded; http.StatusText when empty
60		Header               http.Header // response, whitelisted
61		Body                 []byte      // verbatim; nil when Stub != ""
62		Stub                 string      // "<empty body>" or the HTML summary, as written
63	}
64	
65	// Fixture is one file: a header and one or more exchanges.
66	type Fixture struct {
67		// Name is the file name without ".http"; Scenario is the part of Name before
68		// the identity suffix. Meta.Scenario is a different thing: the free text of the
69		// "# scenario:" header, which need not match the file name.
70		Campaign, Name, Scenario string
71		Identity                 Identity
72		Meta                     Meta
73		Exchanges                []Exchange
74	}
75	
76	var (
77		versionPattern = regexp.MustCompile(`^\d+(\.\d+)+(-[0-9A-Za-z.]+)?$`)
78	
79		requiredHeaders = []string{"scenario", "nexus", "measured", "account", "redacted"}
80		optionalHeaders = []string{"state", "record", "recorded-by"}
81	
82		requestOrder  = []string{"Authorization", "Accept"}
83		responseOrder = []string{
84			"Server", "Docker-Distribution-Api-Version", "Www-Authenticate", "Location", "Link",
85			"Docker-Content-Digest", "Content-Type", "Content-Length",
86		}
87		// displayNames are the header names whose written form is not the
88		// canonical one Go uses as a map key.
89		displayNames = map[string]string{"Www-Authenticate": "WWW-Authenticate"}
90	)
91	
92	func parseErr(fileName, format string, args ...any) error {
93		return fmt.Errorf("nexusfixture: %s: %s", fileName, fmt.Sprintf(format, args...))
94	}
95	
96	// Parse reads one fixture file. fileName is the base name, with ".http". A file
97	// is LF only: a carriage return anywhere is refused. A body line made of "###"
98	// preceded by any number of backslashes is read with one backslash less (Format
99	// writes it with one more), so that a body never reads as the exchange separator.
100	func Parse(campaign, fileName string, data []byte) (Fixture, error) {
101		f := Fixture{Campaign: campaign}
102		name, ok := strings.CutSuffix(fileName, fileSuffix)
103		if !ok {
104			return f, parseErr(fileName, "the file name must end in %s", fileSuffix)
105		}
106		f.Name = name
107		i := strings.LastIndex(name, identitySep)
108		if i < 0 {
109			return f, parseErr(fileName, "no identity suffix, want --admin, --pull or --anon")
110		}
111		f.Scenario, f.Identity = name[:i], Identity(name[i+len(identitySep):])
112		switch f.Identity {
113		case Admin, Pull, Anonymous:
114		default:
115			return f, parseErr(fileName, "unknown identity suffix %q, want admin, pull or anon", string(f.Identity))
116		}
117	
118		if bytes.IndexByte(data, '\r') >= 0 {
119			return f, parseErr(fileName, "the file has a carriage return (CRLF line endings): fixtures use LF only")
120		}
121	
122		meta, rest, err := parseMeta(string(data))
123		if err != nil {
124			return f, parseErr(fileName, "%v", err)
125		}
126		f.Meta = meta
127	
128		chunks := splitExchanges(rest)
129		for n, chunk := range chunks {
130			ex, err := parseExchange(chunk, meta.Record == RecordPending)
131			if err != nil {
132				if len(chunks) > 1 {
133					return f, parseErr(fileName, "exchange %d: %v", n+1, err)
134				}
135				return f, parseErr(fileName, "%v", err)
136			}
137			f.Exchanges = append(f.Exchanges, ex)
138		}
139		return f, nil
140	}
141	
142	// nextLine cuts the first line of s; ok is false when s is empty.
143	func nextLine(s string) (line, rest string, ok bool) {
144		if s == "" {
145			return "", "", false
146		}
147		line, rest, _ = strings.Cut(s, "\n")
148		return line, rest, true
149	}
150	
151	// parseMeta reads the "# key: value" lines and the blank line after them.
152	func parseMeta(text string) (Meta, string, error) {
153		raw := map[string]string{}
154		for strings.HasPrefix(text, "#") {
155			var line string
156			line, text, _ = nextLine(text)
157			body, ok := strings.CutPrefix(line, "# ")
158			if !ok {
159				return Meta{}, "", fmt.Errorf("malformed header line, want \"# key: value\"")
160			}
161			key, value, _ := strings.Cut(body, ":")
162			if !isKnownHeader(key) {
163				return Meta{}, "", fmt.Errorf("unknown header %q", key)
164			}
165			if _, dup := raw[key]; dup {
166				return Meta{}, "", fmt.Errorf("header %q given twice", key)
167			}
168			raw[key] = strings.TrimSpace(value)
169		}
170		for _, key := range requiredHeaders {
171			if raw[key] == "" {
172				return Meta{}, "", fmt.Errorf("missing %s header", key)
173			}
174		}
175		m := Meta{
176			Scenario: raw["scenario"], Measured: raw["measured"], Account: raw["account"], Redacted: raw["redacted"],
177			State: raw["state"], Record: raw["record"], RecordedBy: raw["recorded-by"],
178		}
179		if err := parseNexus(&m, raw["nexus"]); err != nil {
180			return Meta{}, "", err
181		}
182		if err := checkMeasured(m.Measured); err != nil {
183			return Meta{}, "", err
184		}
185		if err := checkRecord(m.Record); err != nil {
186			return Meta{}, "", err
187		}
188		line, rest, ok := nextLine(text)
189		if !ok || line != "" {
190			return Meta{}, "", fmt.Errorf("a blank line must separate the headers from the request")
191		}
192		return m, rest, nil
193	}
194	
195	func isKnownHeader(key string) bool {
196		for _, k := range requiredHeaders {
197			if k == key {
198				return true
199			}
200		}
201		for _, k := range optionalHeaders {
202			if k == key {
203				return true
204			}
205		}
206		return false
207	}
208	
209	// parseNexus reads "<version> <EDITION> [(free text)]".
210	func parseNexus(m *Meta, v string) error {
211		version, rest, _ := strings.Cut(v, " ")
212		edition, rest, _ := strings.Cut(strings.TrimSpace(rest), " ")
213		rest = strings.TrimSpace(rest)
214		if !versionPattern.MatchString(version) {
215			return fmt.Errorf("nexus header: %q is not a version", version)
216		}
217		if edition == "" {
218			return fmt.Errorf("nexus header: the edition is missing after the version")
219		}
220		m.NexusVersion, m.Edition = version, edition
221		if rest == "" {
222			return nil
223		}
224		inner, ok := strings.CutPrefix(rest, "(")
225		if ok {
226			inner, ok = strings.CutSuffix(inner, ")")
227		}
228		if !ok {
229			return fmt.Errorf("nexus header: the text after the edition must be in parentheses")
230		}
231		m.NexusNote = inner
232		return nil
233	}
234	
235	func checkMeasured(v string) error {
236		if len(v) < len("2006-01-02") {
237			return fmt.Errorf("measured header: %q does not start with a YYYY-MM-DD date", v)
238		}
239		if _, err := time.Parse("2006-01-02", v[:10]); err != nil {
240			return fmt.Errorf("measured header: does not start with a YYYY-MM-DD date")
241		}
242		if after := v[10:]; after != "" && !strings.HasPrefix(after, ",") {
243			return fmt.Errorf("measured header: the date may only be followed by \", free text\"")
244		}
245		return nil
246	}
247	
248	func checkRecord(v string) error {
249		if reason, ok := strings.CutPrefix(v, "skip: "); ok && strings.TrimSpace(reason) != "" {
250			return nil
251		}
252		if v == "" || v == "replay" || v == RecordPending {
253			return nil
254		}
255		return fmt.Errorf("record header: %q is not replay, pending or skip: <reason>", v)
256	}
257	
258	// splitExchanges cuts the text after the header at each "###" line.
259	func splitExchanges(text string) []string {
260		parts := strings.Split(text, "\n"+exchangeSep+"\n")
261		for i := 0; i < len(parts)-1; i++ {
262			parts[i] += "\n" // the line break the separator consumed
263		}
264		return parts
265	}
266	
267	func parseExchange(text string, pending bool) (Exchange, error) {
268		var ex Exchange
269		line, text, _ := nextLine(text)
270		fields := strings.Fields(line)
271		if len(fields) != 3 || fields[2] != httpVersion {
272			return ex, fmt.Errorf("request line must be \"METHOD target %s\"", httpVersion)
273		}
274		ex.Method, ex.Target = fields[0], fields[1]
275	
276		header, text, blank, err := readHeaders(text)
277		if err != nil {
278			return ex, fmt.Errorf("request: %w", err)
279		}
280		ex.Host = header.Get("Host")
281		header.Del("Host")
282		ex.RequestHeader = header
283		if ex.Host == "" {
284			return ex, fmt.Errorf("the request has no Host header")
285		}
286	
287		if !blank || text == "" {
288			if pending {
289				return ex, nil
290			}
291			return ex, fmt.Errorf("the response is missing (only a pending fixture may hold a request alone)")
292		}
293		if pending {
294			return ex, fmt.Errorf("a pending fixture must not carry a response")
295		}
296		return ex, parseResponse(&ex, text)
297	}
298	
299	func parseResponse(ex *Exchange, text string) error {
300		line, text, _ := nextLine(text)
301		rest, ok := strings.CutPrefix(line, httpVersion+" ")
302		if !ok {
303			return fmt.Errorf("status line must be \"%s <code> <reason>\"", httpVersion)
304		}
305		code, reason, _ := strings.Cut(rest, " ")
306		status, err := strconv.Atoi(code)
307		if err != nil || status < 100 || status > 599 {
308			return fmt.Errorf("status code is not a number from 100 to 599")
309		}
310		// Format trims the status line, so a blank or padded phrase cannot round-trip.
311		ex.Status, ex.Reason = status, strings.TrimSpace(reason)
312	
313		header, text, blank, err := readHeaders(text)
314		if err != nil {
315			return fmt.Errorf("response: %w", err)
316		}
317		if !blank {
318			return fmt.Errorf("a blank line must separate the response headers from the body")
319		}
320		ex.Header = header
321	
322		body := strings.TrimSuffix(text, "\n")
323		if body == stubEmpty || (strings.HasPrefix(body, stubHTMLStart) && strings.HasSuffix(body, ">")) {
324			ex.Stub = body
325		} else {
326			ex.Body = []byte(unescapeBody(body))
327		}
328		return nil
329	}
330	
331	// isSeparatorLike reports whether a body line is "###" preceded by any number
332	// of backslashes: the lines Format escapes and Parse unescapes.
333	func isSeparatorLike(line string) bool {
334		return strings.HasSuffix(line, exchangeSep) && strings.Trim(line[:len(line)-len(exchangeSep)], `\`) == ""
335	}
336	
337	// mapSeparatorLikeLines applies fn to each body line that isSeparatorLike.
338	func mapSeparatorLikeLines(body string, fn func(string) string) string {
339		lines := strings.Split(body, "\n")
340		for i, l := range lines {
341			if isSeparatorLike(l) {
342				lines[i] = fn(l)
343			}
344		}
345		return strings.Join(lines, "\n")
346	}
347	
348	func escapeBody(body []byte) []byte {
349		return []byte(mapSeparatorLikeLines(string(body), func(l string) string { return `\` + l }))
350	}
351	
352	func unescapeBody(body string) string {
353		return mapSeparatorLikeLines(body, func(l string) string { return l[1:] })
354	}
355	
356	// readHeaders reads "Name: value" lines up to a blank line. blank is false when
357	// the text ended first.
358	func readHeaders(text string) (h http.Header, rest string, blank bool, err error) {
359		h = http.Header{}
360		for {
361			var line string
362			var ok bool
363			line, text, ok = nextLine(text)
364			switch {
365			case !ok:
366				return h, "", false, nil
367			case line == "":
368				return h, text, true, nil
369			case strings.HasPrefix(line, "HTTP/"):
370				return nil, "", false, fmt.Errorf("a blank line must separate the request from the response")
371			}
372			name, value, found := strings.Cut(line, ":")
373			if !found || name == "" {
374				return nil, "", false, fmt.Errorf("malformed header line, want \"Name: value\"")
375			}
376			h.Add(textproto.CanonicalMIMEHeaderKey(name), strings.TrimPrefix(value, " "))
377		}
378	}
379	
380	// Format writes a fixture in the file format; Format(Parse(b)) == b for a file
381	// the recorder or the NX-03 import wrote.
382	func Format(f Fixture) []byte {
383		var b bytes.Buffer
384		writeMeta(&b, f.Meta)
385		for i, ex := range f.Exchanges {
386			if i == 0 {
387				b.WriteString("\n")
388			} else {
389				b.WriteString(exchangeSep + "\n")
390			}
391			writeExchange(&b, ex)
392		}
393		return b.Bytes()
394	}
395	
396	func writeMeta(b *bytes.Buffer, m Meta) {
397		nexus := m.NexusVersion + " " + m.Edition
398		if m.NexusNote != "" {
399			nexus += " (" + m.NexusNote + ")"
400		}
401		lines := []struct{ key, value string }{
402			{"scenario", m.Scenario}, {"nexus", nexus}, {"measured", m.Measured},
403			{"account", m.Account}, {"redacted", m.Redacted},
404		}
405		for _, l := range lines {
406			fmt.Fprintf(b, "# %s: %s\n", l.key, l.value)
407		}
408		for _, l := range []struct{ key, value string }{{"state", m.State}, {"record", m.Record}, {"recorded-by", m.RecordedBy}} {
409			if l.value != "" {
410				fmt.Fprintf(b, "# %s: %s\n", l.key, l.value)
411			}
412		}
413	}
414	
415	func writeExchange(b *bytes.Buffer, ex Exchange) {
416		fmt.Fprintf(b, "%s %s %s\nHost: %s\n", ex.Method, ex.Target, httpVersion, ex.Host)
417		writeHeaders(b, ex.RequestHeader, requestOrder, "Host")
418		if ex.Status == 0 {
419			return
420		}
421		reason := ex.Reason
422		if reason == "" {
423			reason = http.StatusText(ex.Status)
424		}
425		b.WriteString("\n" + strings.TrimSpace(fmt.Sprintf("%s %d %s", httpVersion, ex.Status, reason)) + "\n")
426		writeHeaders(b, ex.Header, responseOrder)
427		b.WriteString("\n")
428		if ex.Stub != "" {
429			b.WriteString(ex.Stub)
430		} else {
431			b.Write(escapeBody(ex.Body))
432		}
433		b.WriteString("\n")
434	}
435	
436	// writeHeaders writes the headers in a fixed order (the preferred names first,
437	// then the others sorted) so that a regeneration does not reshuffle a file.
438	func writeHeaders(b *bytes.Buffer, h http.Header, preferred []string, skip ...string) {
439		skipped := map[string]bool{}
440		for _, s := range skip {
441			skipped[s] = true
442		}
443		var names []string
444		for _, p := range preferred {
445			if _, ok := h[p]; ok && !skipped[p] {
446				names = append(names, p)
447			}
448		}
449		var others []string
450		for k := range h {
451			if skipped[k] || contains(preferred, k) {
452				continue
453			}
454			others = append(others, k)
455		}
456		sort.Strings(others)
457		for _, name := range append(names, others...) {
458			display := name
459			if d, ok := displayNames[name]; ok {
460				display = d
461			}
462			for _, v := range h[name] {
463				fmt.Fprintf(b, "%s: %s\n", display, v)
464			}
465		}
466	}
467	
468	func contains(list []string, s string) bool {
469		for _, v := range list {
470			if v == s {
471				return true
472			}
473		}
474		return false
475	}
