291	// TestRedactLeavesARealAnswerAsItIs: the recorder reads a bench answer, and an
292	// answer that was already clean must come out the same, byte for byte, in the
293	// file (that is what lets it write nothing for an unchanged answer). Stub
294	// fixtures cannot be turned back into a raw body and are left out.
295	func TestRedactLeavesARealAnswerAsItIs(t *testing.T) {
296		all, err := nexusfixture.All()
297		if err != nil {
298			t.Fatal(err)
299		}
300		checked := 0
301		for _, f := range all {
302			for i, ex := range f.Exchanges {
303				if ex.Stub != "" {
304					continue
305				}
306				checked++
307				raw := nexusfixture.RawExchange{
308					Method: ex.Method, Target: ex.Target, Host: ex.Host,
309					RequestHeader: ex.RequestHeader.Clone(), Status: ex.Status,
310					Header: ex.Header.Clone(), Body: slices.Clone(ex.Body),
311				}
312				got := nexusfixture.Redact(raw)
313				got.Reason, ex.Reason = "", "" // the raw answer has none: Format falls back to the standard phrase
314	
315				want, have := f, f
316				want.Exchanges, have.Exchanges = []nexusfixture.Exchange{ex}, []nexusfixture.Exchange{got}
317				if w, h := nexusfixture.Format(want), nexusfixture.Format(have); !bytes.Equal(w, h) {
318					t.Errorf("%s exchange %d: Redact changed a clean answer\nwant:\n%s\ngot:\n%s", f.Name, i+1, w, h)
319				}
320			}
321		}
322		if checked == 0 {
323			t.Fatal("no verbatim exchange was checked: the test is vacuous")
324		}
325	}
