327	// DEVDESK-569 #1: the value of a secret key may be an object or an array. Redact
328	// replaces the whole value, balanced, by "<redacted>": whatever the value held,
329	// strings with brackets or escaped quotes included, leaves no byte behind.
330	func TestRedactSecretKeyWithAnObjectOrArrayValue(t *testing.T) {
331		cases := []struct{ name, in, want, planted string }{
332			{"object", `{"token" : {"v":"zz-obj-1"}}`, `{"token" : "<redacted>"}`, "zz-obj-1"},
333			{"array", `{"password":["zz-arr-1"],"x":1}`, `{"password":"<redacted>","x":1}`, "zz-arr-1"},
334			{"nested", `{"secret":{"a":{"b":["zz-deep-2",{"c":2}]}},"after":true}`, `{"secret":"<redacted>","after":true}`, "zz-deep-2"},
335			{"brackets inside strings do not unbalance it", `{"token":{"a":"}","b":["]",{"c":"zz-br-3"}]},"x":"y"}`, `{"token":"<redacted>","x":"y"}`, "zz-br-3"},
336			{"an escaped quote inside a string", `{"secret":{"a":"q\"}zz-esc-4"},"x":1}`, `{"secret":"<redacted>","x":1}`, "zz-esc-4"},
337			{"several lines", "{\n  \"token\" : {\n    \"v\" : \"zz-ml-5\"\n  },\n  \"n\" : 1\n}", "{\n  \"token\" : \"<redacted>\",\n  \"n\" : 1\n}", "zz-ml-5"},
338			{"an array of objects", `{"password":[{"v":"zz-ao-6"},{"v":"zz-ao-7"}]}`, `{"password":"<redacted>"}`, "zz-ao-6"},
339			{"two secret keys, one of each kind", `{"token":{"v":"zz-two-8"},"secret":"zz-two-9"}`, `{"token":"<redacted>","secret":"<redacted>"}`, "zz-two-8"},
340			{"a secret key nested in the value of another", `{"credentials":{"password":"REDACTED"}}`, `{"credentials":"<redacted>"}`, "REDACTED"},
341		}
342		for _, tc := range cases {
343			t.Run(tc.name, func(t *testing.T) {
344				ex := nexusfixture.Redact(rawJSONExchange(tc.in))
345				if string(ex.Body) != tc.want {
346					t.Errorf("Body =\n%s\nwant\n%s", ex.Body, tc.want)
347				}
348				if bytes.Contains(ex.Body, []byte(tc.planted)) {
349					t.Errorf("Body still holds the secret %q:\n%s", tc.planted, ex.Body)
350				}
351				if !json.Valid(ex.Body) {
352					t.Errorf("Body is not valid JSON any more (the replacement is not balanced):\n%s", ex.Body)
353				}
354				if leaks := nexusfixture.CheckLeaks("x--admin", redactedFixture(t, ex), nil); len(leaks) != 0 {
355					t.Errorf("CheckLeaks on the redacted exchange = %v, want none", leaks)
356				}
357			})
358		}
359	
360		// A value cut short (a truncated recording) cannot be balanced: Redact must
361		// still not keep anything of it.
362		t.Run("an unterminated value keeps nothing", func(t *testing.T) {
363			for _, in := range []string{`{"token":{"v":"zz-cut-11"`, `{"password":["zz-cut-12",`, `{"secret":{"a":"zz-cut-13`} {
364				ex := nexusfixture.Redact(rawJSONExchange(in))
365				if bytes.Contains(ex.Body, []byte("zz-cut-")) {
366					t.Errorf("Redact(%q).Body = %q, still holds the secret", in, ex.Body)
367				}
368			}
369		})
370	}
