420	// DEVDESK-569 #3: a body that is neither JSON nor HTML is not kept: it is
421	// summarised like the HTML stub (its size and its type), since nothing tells
422	// where a secret sits in it. The summary must be one line, hold no byte of the
423	// body, round-trip through the file format as a stub, and pass CheckLeaks.
424	func TestRedactSummarisesABodyThatIsNeitherJSONNorHTML(t *testing.T) {
425		filler := strings.Repeat("&pad=1", 20)
426		cases := []struct {
427			name, contentType, body, mediaType, planted string
428		}{
429			{"plain text", "text/plain", "token=zz-plain-1&x=1" + filler, "text/plain", "zz-plain-1"},
430			{"plain text with a charset", "text/plain; charset=utf-8", "the password is zz-plain-2" + filler, "text/plain", "zz-plain-2"},
431			{"a form", "application/x-www-form-urlencoded", "token=zz-form-3&x=1" + filler, "application/x-www-form-urlencoded", "zz-form-3"},
432			{"octet stream", "application/octet-stream", "zz-bin-4\x00\x01" + filler, "application/octet-stream", "zz-bin-4"},
433			{"XML", "application/xml", "<a><token>zz-xml-5</token></a>" + filler, "application/xml", "zz-xml-5"},
434			{"text that looks like JSON", "text/plain", `{"token":"zz-json-6"}` + filler, "text/plain", "zz-json-6"},
435		}
436		for _, tc := range cases {
437			t.Run(tc.name, func(t *testing.T) {
438				raw := rawJSONExchange("")
439				raw.Header = rawHeader("Server", "Nexus/3.98.1-01 (COMMUNITY)", "Content-Type", tc.contentType)
440				raw.Body = []byte(tc.body)
441				ex := nexusfixture.Redact(raw)
442				if ex.Body != nil {
443					t.Fatalf("Body = %q, want nil: the body must not be kept", ex.Body)
444				}
445				if ex.Stub == "" {
446					t.Fatal("Stub is empty: want a summary of the body")
447				}
448				if strings.ContainsAny(ex.Stub, "\r\n") {
449					t.Errorf("Stub = %q, want one line", ex.Stub)
450				}
451				if strings.Contains(ex.Stub, tc.planted) {
452					t.Errorf("Stub = %q repeats the secret", ex.Stub)
453				}
454				if !strings.Contains(ex.Stub, strconv.Itoa(len(tc.body))) {
455					t.Errorf("Stub = %q, want the body size (%d)", ex.Stub, len(tc.body))
456				}
457				if !strings.Contains(ex.Stub, tc.mediaType) {
458					t.Errorf("Stub = %q, want the media type %q", ex.Stub, tc.mediaType)
459				}
460	
461				data := redactedFixture(t, ex)
462				if bytes.Contains(data, []byte(tc.planted)) {
463					t.Errorf("the formatted fixture holds the secret:\n%s", data)
464				}
465				if leaks := nexusfixture.CheckLeaks("x--admin", data, nil); len(leaks) != 0 {
466					t.Errorf("CheckLeaks = %v, want none:\n%s", leaks, data)
467				}
468				// The file must read it back as a stub (not as a body to replay).
469				f, err := nexusfixture.Parse("c", "synthetic--admin.http", data)
470				if err != nil {
471					t.Fatalf("the fixture does not parse back: %v\n%s", err, data)
472				}
473				if got := f.Exchanges[0]; got.Stub != ex.Stub || got.Body != nil {
474					t.Errorf("parsed back Stub = %q, Body = %q, want the stub %q and no body", got.Stub, got.Body, ex.Stub)
475				}
476			})
477		}
478	
479		// What stays a body: JSON, in any of its media types.
480		for _, ct := range []string{
481			"application/json", "application/json;charset=utf-8", "Application/JSON",
482			"application/vnd.docker.distribution.manifest.v2+json", "application/vnd.oci.image.index.v1+json",
483		} {
484			t.Run("JSON is kept: "+ct, func(t *testing.T) {
485				raw := rawJSONExchange(`{"repositories":["api"]}`)
486				raw.Header = rawHeader("Content-Type", ct)
487				if ex := nexusfixture.Redact(raw); ex.Stub != "" || string(ex.Body) != `{"repositories":["api"]}` {
488					t.Errorf("Stub = %q, Body = %q, want the JSON body kept", ex.Stub, ex.Body)
489				}
490			})
491		}
492		t.Run("HTML is still the HTML stub", func(t *testing.T) {
493			raw := rawJSONExchange("")
494			raw.Header = rawHeader("Content-Type", "text/html;charset=utf-8")
495			raw.Body = []byte(rawHTML)
496			if ex := nexusfixture.Redact(raw); !strings.HasPrefix(ex.Stub, "<HTML body omitted:") || ex.Body != nil {
497				t.Errorf("Stub = %q, Body = %q, want the HTML stub", ex.Stub, ex.Body)
498			}
499		})
500	}
